        el.addEventListener('mouseleave', () => {
            var tooltip = document.querySelector('.tooltip')
            if(tooltip) {
                tooltip.remove()
            }
        })
    }
}

import type { ParsedResult } from '@/parsers/tag'
import { isParameterChecked, parseFunction, tagRegex } from '@/parsers/tag'

// Values typed into a prompt tag live only in this page's memory, never in storage. A prompt is known by its whole
// text in its workspace, so one environment variable used in many requests is one prompt, while prompts with another
// title, or the same prompt in another workspace, are not
const rememberedValues = new Map<string, string>() // Ask once, until the app closes or Forget
const lastValues = new Map<string, string>() // Ask every send, pre-filled
// Ask once while its box is open, so another send waits for the same answer
const onceValuesAsked = new Map<string, Promise<string>>()

// one box at a time, a send can reach several prompts at once
let dialogQueue: Promise<unknown> = Promise.resolve()

// plain characters, which a url keeps as they are, so a saved url shows them in every version
const MASKED_PREVIEW = '******'

function readParameters(parsedTag: ParsedResult, workspaceId?: string) {
    const text = (name: string) => {
        const value = parsedTag.parameters[name]
        return value === undefined ? '' : String(value)
    }

    const ask = text('ask')

    return {
        promptKey: JSON.stringify(parsedTag),
        // the key of a value kept past the send, none outside a workspace
        keptKey: workspaceId === undefined ? undefined : JSON.stringify([workspaceId, parsedTag]),
        title: text('title'),
        label: text('label'),
        defaultValue: text('defaultValue'),
        mask: isParameterChecked(parsedTag.parameters.mask),
        // always when missing or unknown: asks on every send
        ask: ask === 'once' || ask === 'prefill' ? ask : 'always',
    }
}

function getRememberedValue(parsedTag: ParsedResult, workspaceId: string | undefined) {
    const { keptKey, ask } = readParameters(parsedTag, workspaceId)
    return ask === 'once' && keptKey !== undefined ? rememberedValues.get(keptKey) : undefined
}

function askForValue(title: string, defaultValue: string, label: string, mask: boolean): Promise<string | null> {
    const dialog = dialogQueue.then(() => window.createPrompt(title, defaultValue, [], { label: label === '' ? undefined : label, mask }))
    dialogQueue = dialog.catch(() => undefined)
    return dialog
}

// Outside a send, such as the URL preview and the tag editor, a prompt shows its remembered value in workspaceId, else
// the default, never opening the box
export function getPromptPreviewValue(parsedTag: ParsedResult, workspaceId: string | undefined) {
    const { defaultValue, mask } = readParameters(parsedTag)

    if (mask) {
        return MASKED_PREVIEW
    }

    return getRememberedValue(parsedTag, workspaceId) ?? defaultValue
}

// A prompt in a send of a request in workspaceId. sendValues are the values this send was given, so a prompt used twice in one send asks once.
// onMaskedPrompt tells the text being resolved that a masked value went into it. hideMasked shows a send's text once it
// is resolved: masked values as ******, the others as this send resolved them
export async function handlePromptTag(parsedTag: ParsedResult, workspaceId: string, sendValues: Map<string, Promise<string>>, onMaskedPrompt: () => void, hideMasked: boolean): Promise<string> {
    const { promptKey, title, label, defaultValue, mask, ask } = readParameters(parsedTag)
    const keptKey = JSON.stringify([workspaceId, parsedTag])

    if (mask && hideMasked) {
        return MASKED_PREVIEW
    }

    if (mask) {
        onMaskedPrompt()
    }

    const rememberedValue = getRememberedValue(parsedTag, workspaceId)

    if (rememberedValue !== undefined) {
        return rememberedValue
    }

    const sendValue = sendValues.get(promptKey) ?? (ask === 'once' ? onceValuesAsked.get(keptKey) : undefined)

    if (sendValue !== undefined) {
        sendValues.set(promptKey, sendValue)
        return sendValue
    }

    const boxValue = (ask === 'prefill' ? lastValues.get(keptKey) : undefined) ?? defaultValue

    const boxTitle = title === '' ? 'Enter value' : title

    const valuePromise = askForValue(boxTitle, boxValue, label, mask).then(value => {
        if (value === null) {
            throw new PromptCancelledError(`Prompt "${boxTitle}" was cancelled`, { cause: 'display-error' })
        }

        if (ask === 'once') {
            rememberedValues.set(keptKey, value)
        }

        if (ask === 'prefill') {
            lastValues.set(keptKey, value)
        }

        return value
    })

    sendValues.set(promptKey, valuePromise)

    if (ask === 'once') {
        onceValuesAsked.set(keptKey, valuePromise)
        valuePromise.catch(() => undefined).finally(() => onceValuesAsked.delete(keptKey))
    }

    return valuePromise
}

// Cancel in a prompt box, which stops the send
export class PromptCancelledError extends Error {}

// how many prompts keep a value in every workspace, a prompt keeps at most one
export function countRememberedPromptValues() {
    return rememberedValues.size + lastValues.size
}

// forgets them in every workspace, returns how many values were forgotten
export function forgetPromptValues() {
    const forgottenCount = countRememberedPromptValues()
    rememberedValues.clear()
    lastValues.clear()
    return forgottenCount
}

// A script reads a variable synchronously and cannot open the box, so a prompt tag in it reads as the remembered
// value in workspaceId or the default. onMaskedPrompt is told when a masked one is read
export function replacePromptTagsWithKnownValues(value: string, workspaceId: string | undefined, onMaskedPrompt?: () => void) {
    return value.replace(tagRegex, (match, tag: string) => {
        let parsedTag: ParsedResult

        try {
            parsedTag = parseFunction(tag, true)
        } catch {
            // text that only looks like a tag is read as written, as it was before prompt tags
            return match
        }

        if (parsedTag.functionName !== 'prompt') {
            return match
        }

        const { defaultValue, mask } = readParameters(parsedTag)

        if (mask) {
            onMaskedPrompt?.()
        }

        return getRememberedValue(parsedTag, workspaceId) ?? defaultValue
    })
}

// titles hold names from collection data, and a prompt tag's title, label and default come from it, which may have been imported
function escapeHtml(text: string) {
    return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;')
}

interface PromptOptions {
    label?: string
    mask?: boolean
}

class AlertConfirmPrompt extends HTMLElement {
    constructor() {
        super()
        this.attachShadow({ mode: 'open' })
    }

    createDialog = (type: 'prompt' | 'confirm' | 'alert', title: string, defaultValue = '', selectList = [], options?: PromptOptions) => {
        const div = document.createElement('div')

        let inputHtml = ''
        if (type === 'prompt') {
            // given options, a plain text or password box, whatever the title says
            if (options) {
                inputHtml = `
                <div style="margin-top: 0.5rem;">
                    ${options.label !== undefined ? `<div class="dialog-label">${escapeHtml(options.label)}</div>` : ''}
                    <input type="${options.mask ? 'password' : 'text'}" value="${escapeHtml(defaultValue ?? '')}" class="dialog-input" id="dialog-input" spellcheck="false" autocomplete="off">
                </div>
                `
            } else if (title.toLowerCase().includes('color')) {
                inputHtml = `
                <div style="margin-top: 0.5rem;">
                    <input type="color" value="${defaultValue ?? '#000000'}" class="color-preview" id="dialog-color-input">
                </div>
                `
            }  else if(title.toLowerCase().includes('in seconds')) {
                inputHtml = `
                <div style="margin-top: 0.5rem;">
                    <input type="number" value="${defaultValue ?? ''}" list="selectList" class="dialog-input" id="dialog-input" spellcheck="false">
                    <datalist id="selectList">
                        ${selectList.map(item => `<option value="${item}"></option>`).join('')}
                    </datalist>
                </div>
                `
            } else {
                inputHtml = `
                <div style="margin-top: 0.5rem;">
                    <input type="text" value="${defaultValue ?? ''}" list="selectList" class="dialog-input" id="dialog-input" spellcheck="false">
                    <datalist id="selectList">
                        ${selectList.map(item => `<option value="${item}"></option>`).join('')}
                    </datalist>
                </div>
                `
            }
        }

        div.innerHTML = `
        <div class="dialog-container">
            <div class="dialog dialog-${type}">
                <div>${escapeHtml(title)}</div>
                ${inputHtml}
                <div style="margin-top: 1rem; text-align: right; user-select: none;">
                    <button class="dialog-primary-button" id="dialog-confirm">OK</button>
                    ${type !== 'alert' ? '<button class="dialog-secondary-button" id="dialog-cancel">Cancel</button>' : ''}
                </div>
            </div>
        </div>
        `

        const shadowRoot = this.shadowRoot

        if (shadowRoot === null) {
            throw new Error('Shadow root is null')
        }

        shadowRoot.querySelector('#root')?.appendChild(div)

        if (type === 'prompt') {
            if (title.toLowerCase().includes('color') && !options) {
                shadowRoot.getElementById('dialog-color-input')?.focus()
            } else {
                shadowRoot.getElementById('dialog-input')?.focus()
                ;(shadowRoot.getElementById('dialog-input') as HTMLInputElement).select()
            }
        } else {
            shadowRoot.getElementById('dialog-confirm')?.focus()
        }

        return new Promise((resolve) => {
            if (this === null) {
                throw new Error('Shadow root is null')
            }

            const closeModal = () => {
                shadowRoot.removeEventListener('click', eventHandler)
                shadowRoot.removeEventListener('keyup', eventHandler)
                shadowRoot.removeEventListener('keydown', eventHandler)
                shadowRoot.querySelector('#root')?.removeChild(div)
            }

            const confirm = () => {
                if (type === 'prompt') {
                    if (title.toLowerCase().includes('color') && !options) {
                        resolve((shadowRoot.getElementById('dialog-color-input') as HTMLInputElement).value)
                    } else {
                        resolve((shadowRoot.getElementById('dialog-input') as HTMLInputElement).value)
                    }
                } else {
                    resolve(true)
                }
                closeModal()
            }

            const cancel = () => {
                resolve(type === 'prompt' ? null : false)
                closeModal()
            }

            const eventHandler = (e: any) => {
                if (e.type === 'keyup') {
                    if (e.key === 'Enter') {
                        confirm()
                    }

                    if (e.key === 'Escape') {
                        cancel()
                    }

                    return
                }

                // Trap focus inside dialog
                if (e.type === 'keydown') {
                    const focusableEls = div.querySelectorAll('button:not(:disabled), input[type="text"]:not(:disabled), input[type="password"]:not(:disabled), input[type="color"]:not(:disabled)') as NodeListOf<HTMLElement>
                    const firstFocusableEl = focusableEls[0]
                    const lastFocusableEl = focusableEls[focusableEls.length - 1]

                    const isTabPressed = e.key === 'Tab'
                    if (!isTabPressed) {
                        return
                    }

                    if (e.shiftKey) {
                        if (shadowRoot && shadowRoot.activeElement === firstFocusableEl) {
                            lastFocusableEl.focus()
                            e.preventDefault()
                        }
                    } else {
                        if (shadowRoot && shadowRoot.activeElement === lastFocusableEl) {
                            firstFocusableEl.focus()
                            e.preventDefault()
                        }
                    }
                    return
                }

                const target = e.composedPath()[0]

                if (target.id === 'dialog-confirm') {
                    confirm()
                }

                if (target.id === 'dialog-cancel') {
                    cancel()
                }
            }

            shadowRoot.addEventListener('click', eventHandler)
            shadowRoot.addEventListener('keyup', eventHandler)
            shadowRoot.addEventListener('keydown', eventHandler)
        })
    }

    createPrompt = (title: string, defaultValue = '', selectList = [], options?: PromptOptions) => {
        return this.createDialog('prompt', title, defaultValue, selectList, options)
    }

    createConfirm = (title: string) => {
        return this.createDialog('confirm', title)
    }

    createAlert = (message: string) => {
        return this.createDialog('alert', message)
    }

    connectedCallback() {
        if (this.shadowRoot === null) {
            return
        }

        this.shadowRoot.innerHTML = /* html */ `
        <div id="root"></div>
        <style>
        .dialog-container {
            position: fixed;
            height: 100vh;
            width: 100vw;
            display: grid;
            place-items: center;
            top: 0;
            left: 0;
            z-index: 9999;
            --border-radius: 3px;
        }

        .dialog {
            background-color: var(--modal-background-color);
            color: var(--modal-text-color);
            padding: 1rem;
            box-shadow: 1px 1px 42px -16px black;
            border-radius: 4px;
            border: 1px solid var(--modal-border-color);
            word-break: break-word;
        }

        .dialog-confirm, .dialog-alert {
            width: 20rem;
            padding: 1.5rem;
        }

        .dialog *::selection {
            background: #9cc3f5;
        }

        .dialog-primary-button, .dialog-secondary-button {
            padding: 8px 16px;
            border-radius: var(--border-radius);
            cursor: pointer;
        }

        .dialog-primary-button {
            background: var(--primary-background-color);
            color: var(--primary-text-color);
            border: none;
            width: 75px;
        }

        .dialog-primary-button:hover {
            background: var(--primary-hover-background-color);
        }

        .dialog-secondary-button {
            margin-left: 0.5rem;
            background: var(--button-background-color);
            color: var(--button-text-color);
            border: 1px solid var(--button-border-color);
        }

        .dialog-secondary-button:hover {
            background: var(--button-hover-background-color);
        }

        .dialog-input {
            padding: 7px;
            width: 25rem;
            border-radius: var(--border-radius);
            border: 1px solid var(--input-border-color);
            caret-color: var(--modal-caret-color);
            background-color: var(--modal-background-color);
            color: var(--text-color);
        }

        .dialog-label {
            margin-bottom: 0.25rem;
            font-size: 0.9rem;
        }

        .color-preview {
            padding: 7px;
            height: 5rem;
            width: 5rem;
            caret-color: var(--modal-caret-color);
            background-color: var(--modal-background-color);
            color: var(--text-color);
            cursor: pointer;
        }

        .dialog-input::selection {
            background-color: var(--modal-input-selection-background-color);
        }

        .dialog-input:focus {
            outline: 1px solid var(--input-highlight-outline-color);
            border: 1px solid var(--input-highlight-outline-color);
            background-color: var(--modal-background-color);
            color: var(--text-color);
        }

        @media (max-width: 768px) {
            .dialog {
                max-width: calc(100vw - 2rem);
                box-sizing: border-box;
            }

            .dialog-input {
                max-width: 100%;
                box-sizing: border-box;
            }
        }
        </style>
        `

        if (this.getAttribute('attach-to-window') === 'true') {
            window.createPrompt = this.createPrompt
            window.createConfirm = this.createConfirm
            window.createAlert = this.createAlert
        }
    }
}

customElements.define('alert-confirm-prompt', AlertConfirmPrompt)
